import{_ as p,a0 as l,w as o,s as d,ao as r,I as t,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"改進你的腳本程序的 5 個方法 | LCTT x X-CMD","titleTemplate":false,"description":"改進你的腳本程序的 5 個方法 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"改進你的腳本程序的 5 個方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"改進你的腳本程序的 5 個方法 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20200107 5 ways to improve your Bash scripts","title":"改進你的腳本程序的 5 個方法","tag":"202108","desc":""},"relativePath":"202108/20200107 5 ways to improve your Bash scripts.md","filePath":"[post].md"}'),h={name:"202108/20200107 5 ways to improve your Bash scripts.md"};function c(u,s,g,k,b,f){const e=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="改進你的腳本程序的-5-個方法" tabindex="-1">改進你的腳本程序的 5 個方法 <a class="header-anchor" href="#改進你的腳本程序的-5-個方法" aria-label="Permalink to “改進你的腳本程序的 5 個方法”">​</a></h1><blockquote><p>巧用 Bash 腳本程序能幫助你完成很多極具挑戰的任務。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/25/131347yblk4jg4r6blebmg.jpg" alt=""></p><p>系統管理員經常寫腳本程序，不論長短，這些腳本可以完成某種任務。</p><p>你是否曾經查看過某個軟件發行方提供的安裝用的<ruby>腳本<rt>script</rt></ruby>程序？為了能夠適應不同用户的系統配置，順利完成安裝，這些腳本程序經常包含很多函數和邏輯分支。多年來，我積累了一些改進腳本程序的一些技巧，這裏分享幾個，希望能對朋友們也有用。這裏列出一組短腳本示例，展示給大家做腳本樣本。</p><h3 id="初步嘗試" tabindex="-1">初步嘗試 <a class="header-anchor" href="#初步嘗試" aria-label="Permalink to “初步嘗試”">​</a></h3><p>我嘗試寫一個腳本程序時，原始程序往往就是一組命令列，通常就是調用標準命令完成諸如更新網頁內容之類的工作，這樣可以節省時間。其中一個類似的工作是解壓文件到 Apache 網站服務器的主目錄裏，我的最初腳本程序大概是下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp january_schedule.tar.gz /usr/apache/home/calendar/</span></span>
<span class="line"><span>cd /usr/apache/home/calendar/</span></span>
<span class="line"><span>tar zvxf january_schedule.tar.gz</span></span></code></pre></div><p>這幫我節省了時間，也減少了鍵入多條命令操作。時日久了，我掌握了另外的技巧，可以用 Bash 腳本程序完成更難的一些工作，比如説創建軟件安裝包、安裝軟件、備份文件系統等工作。</p><h3 id="_1、條件分支結構" tabindex="-1">1、條件分支結構 <a class="header-anchor" href="#_1、條件分支結構" aria-label="Permalink to “1、條件分支結構”">​</a></h3><p>和眾多其他編程語言一樣，腳本程序的條件分支結構同樣是強大的常用技能。條件分支結構賦予了計算機程序邏輯能力，我的很多實例都是基於條件邏輯分支。</p><p>基本的條件分支結構就是 <code>if</code> 條件分支結構。通過判定是否滿足特定條件，可以控制程序選擇執行相應的腳本命令段。比如説，想要判斷系統是否安裝了 Java ，可以通過判斷系統有沒有一個 Java 庫目錄；如果找到這個目錄，就把這個目錄路徑添加到可運行程序路徑，也就可以調用 Java 庫應用了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -d &quot;$JAVA_HOME/bin&quot; ] ; then</span></span>
<span class="line"><span>    PATH=&quot;$JAVA_HOME/bin:$PATH&quot;</span></span></code></pre></div><h3 id="_2、限定運行權限" tabindex="-1">2、限定運行權限 <a class="header-anchor" href="#_2、限定運行權限" aria-label="Permalink to “2、限定運行權限”">​</a></h3><p>你或許想只允許特定的用户才能執行某個腳本程序。除了 Linux 的權限許可管理，比如對用户和用户組設定權限、通過 SELinux 設定此類的保護權限等，你還可以在腳本里設置邏輯判斷來設置執行權限。類似的情況可能是，你需要確保只有網站程序的所有者才能執行相應的網站初始化操作腳本。甚至你可以限定只有 root 用户才能執行某個腳本。這個可以通過在腳本程序裏設置邏輯判斷實現，Linux 提供的幾個環境變量可以幫忙。其中一個是保存用户名稱的變量 <code>$USER</code>， 另一個是保存用户識別碼的變量 <code>$UID</code> 。在腳本程序裏，執行用户的 UID 值就保存在 <code>$UID</code> 變量裏。</p><h4 id="用户名判別" tabindex="-1">用户名判別 <a class="header-anchor" href="#用户名判別" aria-label="Permalink to “用户名判別”">​</a></h4><p>第一個例子裏，我在一個帶有幾個應用服務器實例的多用户環境裏指定只有用户 <code>jboss1</code> 可以執行腳本程序。條件 <code>if</code> 語句主要是判斷，“要求執行這個腳本程序的用户不是 <code>jboss1</code> 嗎?”當此條件為真時，就會調用第一個 <code>echo</code> 語句，接着是 <code>exit 1</code>，即退出這個腳本程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ &quot;$USER&quot; != &#39;jboss1&#39; ]; then</span></span>
<span class="line"><span>     echo &quot;Sorry, this script must be run as JBOSS1!&quot;</span></span>
<span class="line"><span>     exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>echo &quot;continue script&quot;</span></span></code></pre></div><h4 id="根用户判別" tabindex="-1">根用户判別 <a class="header-anchor" href="#根用户判別" aria-label="Permalink to “根用户判別”">​</a></h4><p>接下來的例子是要求只有根用户才能執行腳本程序。根用户的用户識別碼（UID）是 ０，設置的條件判斷採用大於操作符（<code>-gt</code>），所有 UID 值大於 ０ 的用户都被禁止執行該腳本程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ &quot;$UID&quot; -gt 0 ]; then</span></span>
<span class="line"><span>     echo &quot;Sorry, this script must be run as ROOT!&quot;</span></span>
<span class="line"><span>     exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>echo &quot;continue script&quot;</span></span></code></pre></div><h3 id="_3、帶參數執行程序" tabindex="-1">3、帶參數執行程序 <a class="header-anchor" href="#_3、帶參數執行程序" aria-label="Permalink to “3、帶參數執行程序”">​</a></h3><p>可執行程序可以附帶參數作為執行選項，命令列腳本程序也是一樣，下面給出幾個例子。在這之前，我想告訴你，能寫出好的程序並不只是寫出我們想要它執行什麼的程序，程序還需要不執行我們不要它執行的操作。如果運行程序時沒有提供參數造成程序缺少足夠信息，我願意腳本程序不要做任何破壞性的操作。因而，程序的第一步就是確認命令列是否提供了參數，判定的條件就是參數數量 <code>$#</code> 是否為 0 ，如果是（意味着沒有提供參數），就直接終止腳本程序並退出操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ $# -eq 0 ]; then</span></span>
<span class="line"><span>    echo &quot;No arguments provided&quot;</span></span>
<span class="line"><span>    exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>echo &quot;arguments found: $#&quot;</span></span></code></pre></div><h4 id="多個運行參數" tabindex="-1">多個運行參數 <a class="header-anchor" href="#多個運行參數" aria-label="Permalink to “多個運行參數”">​</a></h4><p>可以傳遞給腳本程序的參數不止一個。腳本使用內部變量指代這些參數，內部變量名用非負整數遞增標識，也就是 <code>$1</code>、<code>$2</code>、<code>$3</code> 等等遞增。我只是擴展前面的程序，並在下面一行輸出顯示用户提供的前三個參數。顯然，要針對所有的每個參數有對應的響應需要更多的邏輯判斷，這裏的例子只是簡單展示參數的使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $1 $2 $3</span></span></code></pre></div><p>我們在討論這些參數變量名，你或許有個疑問，“參數變量名怎麼跳過了 <code>$0</code>，（而直接從<code>$1</code> 開始）？”</p><p>是的，是這樣，這是有原因的。變量名 <code>$0</code> 確實存在，也非常有用，它儲存的是被執行的腳本程序的名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $0</span></span></code></pre></div><p>程序執行過程中有一個變量名指代程序名稱，很重要的一個原因是，可以在生成的日誌文件名稱裏包含程序名稱，最簡單的方式應該是調用一個 <code>echo</code> 語句。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo test &gt;&gt; $0.log</span></span></code></pre></div><p>當然，你或許要增加一些代碼，確保這個日誌文件存放在你希望的路徑，日誌名稱包含你認為有用的信息。</p><h3 id="_4、交互輸入" tabindex="-1">4、交互輸入 <a class="header-anchor" href="#_4、交互輸入" aria-label="Permalink to “4、交互輸入”">​</a></h3><p>腳本程序的另一個好用的特性是可以在執行過程中接受輸入，最簡單的情況是讓用户可以輸入一些信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;enter a word please:&quot;</span></span>
<span class="line"><span>read word</span></span>
<span class="line"><span>echo $word</span></span></code></pre></div><p>這樣也可以讓用户在程序執行中作出選擇。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>read -p &quot;Install Software ?? [Y/n]: &quot; answ</span></span>
<span class="line"><span>if [ &quot;$answ&quot; == &#39;n&#39; ]; then</span></span>
<span class="line"><span>    exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>    echo &quot;Installation starting...&quot;</span></span></code></pre></div><h3 id="_5、出錯退出執行" tabindex="-1">5、出錯退出執行 <a class="header-anchor" href="#_5、出錯退出執行" aria-label="Permalink to “5、出錯退出執行”">​</a></h3><p>幾年前，我寫了個腳本，想在自己的電腦上安裝最新版本的 Java 開發工具包（JDK）。這個腳本把 JDK 文件解壓到指定目錄，創建更新一些符號鏈接，再做一下設置告訴系統使用這個最新的版本。如果解壓過程出現錯誤，在執行後面的操作就會使整個系統上的 Java 破壞不能使用。因而，這種情況下需要終止程序。如果解壓過程沒有成功，就不應該再繼續進行之後的更新操作。下面語句段可以完成這個功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tar kxzmf jdk-8u221-linux-x64.tar.gz -C /jdk --checkpoint=.500; ec=$?</span></span>
<span class="line"><span>if [ $ec -ne 0 ]; then</span></span>
<span class="line"><span>     echo &quot;Installation failed - exiting.&quot;</span></span>
<span class="line"><span>     exit 1</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>下面的單行語句可以給你快速展示一下變量 <code>$?</code> 的用法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls T; ec=$?; echo $ec</span></span></code></pre></div><p>先用 <code>touch T</code> 命令創建一個文件名為 <code>T</code> 的文件，然後執行這個單行命令，變量 <code>ec</code> 的值會是 ０。然後，用 <code>rm T</code> 命令刪除文件，再執行該單行命令，變量 <code>ec</code> 的值會是 ２，因為文件 <code>T</code> 不存在，命令 <code>ls</code> 找不到指定文件報錯。</p><p>在邏輯條件裏利用這個出錯標識，參照前文我使用的條件判斷，可以使腳本文件按需完成設定操作。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>要完成複雜的功能，或許我們覺得應該使用諸如 Python、C 或 Java 這類的高級編程語言，然而並不盡然，腳本編程語言也很強大，可以完成類似任務。要充分發揮腳本的作用，有很多需要學習的，希望這裏的幾個例子能讓你意識到腳本編程的強大。</p><hr>`,48)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/20/1/improve-bash-scripts"},{default:n(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/20/1/improve-bash-scripts",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/alanfdoss"},{default:n(()=>[...s[2]||(s[2]=[a("Alan Formy-Duval",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(e,{href:"https://github.com/fisherue"},{default:n(()=>[...s[4]||(s[4]=[a("fisherue",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const v=p(h,[["render",c]]);export{x as __pageData,v as default};
